"          const o = JSON.parse(localStorage.getItem('vorder'));\n"
"          if (Array.isArray(o))\n"
"            widgets.sort((a, b) => (o.indexOf(a.k) + 1 || 1e9) - (o.indexOf(b.k) + 1 || 1e9));\n"
"        } catch (e) { }\n"
"        saveWidgets();\n"
"      }\n"
"      widgets = widgets.filter(w => w.t === 'bar' || w.t === 'flow' || w.t === 'vol' || w.t === 'tot' || w.t === 'bit' || (w.t === 'cval' && CUSTOM[w.k]) ||\n"
"        (w.src && (w.src === 'rate' || VFLOATS.includes(w.src) || VUINTS.includes(w.src))));\n"
"      for (const w of widgets) if (w.t === 'bar' && !BARM[w.mode]) w.mode = 'qmax';\n"
"      for (const w of widgets) if ((w.t === 'vol' || w.t === 'tot') && !VOLU[w.vol]) w.vol = 'l';\n"
"      for (const w of widgets) if (w.t === 'tot' && !TOTM[w.m]) w.m = 'plus';\n"
"      for (const w of widgets)\n"
"        if (w.t === 'bit' && (!(w.src in FLAGS) || !(w.b >= 0 && w.b < FLAGS[w.src].length))) { w.src = 'setpoint'; w.b = 0 }\n"
"      for (const w of widgets) if (w.t === 'bit' && !/^#[0-9a-fA-F]{6}$/.test(w.col || '')) w.col = BITCOL[0];\n"
"      for (const w of widgets) if (w.t === 'bar' && !BARM[w.mode]) w.mode = 'qmax';\n"
"      for (const b of baseWidgets())\n"
"        if (b.t !== 'bar' && b.t !== 'flow' && b.t !== 'vol' && b.t !== 'tot' &&\n"
"            !widgets.some(w => w.k === b.k))\n"
"          widgets.push(b);\n"
"    }\n"
"    function widgetName(w) {\n"
"      if (w.t === 'chart') return 'График: Расход, 10 мин';\n"
"      if (w.t === 'bar') return 'Бар: ' + (BARM[w.mode] ? BARM[w.mode].n : w.mode);\n"
"      if (w.t === 'cval') return (CUSTOM[w.k] && CUSTOM[w.k].label) || w.k;\n"
"      if (w.t === 'flow') return 'Расход, ' + VOLN[w.vol] + '/' + TIMN[w.time];\n"
"      if (w.t === 'vol') return 'Общий, ' + VOLN[w.vol];\n"
"      if (w.t === 'tot') return TOTM[w.m].n + ', ' + VOLN[w.vol];\n"
"      if (w.t === 'bit') return (FLBL[FLAGS[w.src][w.b]] || FLAGS[w.src][w.b]);\n"
"      return LBL[w.src] || w.src;\n"
"    }\n"
"    function widgetHtml(w) {\n"
"      if (w.t === 'chart')\n"
"        return '<div class=\"vcard chart\" data-k=\"' + w.k + '\"><div class=\"vname\">Расход, последние 10 мин</div><canvas id=\"rateChart\"></canvas></div>';\n"
"      if (w.t === 'val')\n"
"        return '<div class=\"vcard\" data-k=\"' + w.k + '\"><div class=\"vname\">' + (LBL[w.src] || w.src) + '</div><div class=\"vval\" id=\"vf_' + w.src + '\">—</div></div>';\n"
"      if (w.t === 'cval') \n"
"        return '<div class=\"vcard\" data-k=\"' + w.k + '\"><div class=\"vname\">' + widgetName(w) + '</div><div class=\"vval\" id=\"vfc_' + w.k + '\">—</div></div>';\n"
"      if (w.t === 'flow') \n"
"        return '<div class=\"vcard\" data-k=\"' + w.k + '\"><div class=\"vname\">' + widgetName(w) + '</div><div class=\"vval\" id=\"vfl_' + w.k + '\">—</div></div>';\n"
"      if (w.t === 'vol') \n"
"        return '<div class=\"vcard\" data-k=\"' + w.k + '\"><div class=\"vname\">' + widgetName(w) + '</div><div class=\"vval\" id=\"vvv_' + w.k + '\">—</div></div>';\n"
"      if (w.t === 'tot') \n"
"        return '<div class=\"vcard\" data-k=\"' + w.k + '\"><div class=\"vname\">' + widgetName(w) + '</div><div class=\"vval\" id=\"vtv_' + w.k + '\">—</div></div>';\n"
"      if (w.t === 'bit') \n"
"        return '<div class=\"vcard wbit\" data-k=\"' + w.k + '\"><div class=\"vname\">' + widgetName(w) + '</div><div class=\"bitlamp\" id=\"bl_' + w.k + '\"></div></div>';\n"
"      return '<div class=\"vcard wbar\" data-k=\"' + w.k + '\"><div class=\"vname\">' + widgetName(w).replace('Бар: ', '') + '<span class=\"bpct\" id=\"bp_' + w.k + '\"></span></div><div class=\"hbar\"><div class=\"hfill\" id=\"hf_' + w.k + '\"></div></div></div>';\n"
"    }\n"
"    function vBuild() {\n"
"      loadWidgets();\n"
"      $('values').innerHTML = widgets.filter(w => w.on).map(widgetHtml).join('');\n"
"      vBuilt = true; rateDraw(); setDrag(); renderPanel();\n"
"    }\n"
"    let editing = false;\n"
"    function toggleEdit() {\n"
"      editing = !editing;\n"
"      document.body.className = editing ? 'edit' : '';\n"
"      $('btnEdit').classList.toggle('act', editing);\n"
"      setDrag();\n"
"    }\n"
"    function setDrag() {\n"
"      const el = $('values'); if (!el) return;\n"
"      [...el.children].forEach(c => c.draggable = editing);\n"
"    }\n"
"    let dragK = null;\n"
"    document.addEventListener('dragstart', e => {\n"
"      const c = e.target.closest && e.target.closest('.vcard');\n"
"      if (!editing || !c) return;\n"
"      dragK = c.dataset.k; c.classList.add('dragging');\n"
"      e.dataTransfer.effectAllowed = 'move';\n"
"    });\n"
"    document.addEventListener('dragend', e => {\n"
"      const c = e.target.closest && e.target.closest('.vcard');\n"
"      if (c) c.classList.remove('dragging');\n"
"      dragK = null;\n"
"    });\n"
"    document.addEventListener('dragover', e => {\n"
"      if (!editing || !dragK) return;\n"
"      if (e.target.closest && e.target.closest('.vcard')) e.preventDefault();\n"
"    });\n"
"    document.addEventListener('drop', e => {\n"
"      const c = e.target.closest && e.target.closest('.vcard');\n"
"      if (!editing || !dragK || !c || c.dataset.k === dragK) return;\n"
"      e.preventDefault();\n"
"      const src = document.querySelector('.vcard[data-k=\"' + dragK + '\"]');\n"
"      if (!src) return;\n"
"      const r = c.getBoundingClientRect();\n"
"      const after = (e.clientY - r.top) > r.height / 2 || (e.clientX - r.left) > r.width / 2;\n"
"      c.parentNode.insertBefore(src, after ? c.nextSibling : c);\n"
"      const ord = [...$('values').children].map(x => x.dataset.k);\n"
"      widgets.sort((a, b) =>\n"
"        (ord.indexOf(a.k) + 1 || 1e9) - (ord.indexOf(b.k) + 1 || 1e9));\n"
"      saveWidgets();\n"
"    });\n"
"    function toggleW() {\n"
"      const p = $('wpanel');\n"
"      p.hidden = !p.hidden;\n"
"      $('btnW').classList.toggle('act', !p.hidden);\n"
"      renderPanel();\n"
"    }\n"
"    function renderPanel() {\n"
"      const p = $('wlist'); if (!p) return;\n"
"      let h = '<div class=\"wrow\"><button id=\"btnWsave\" onclick=\"wSave()\">Сохранить в шлюз</button>' +\n"
"        '<span id=\"wmsg\" class=\"flash\">' + (wDirty ? 'не сохранено' : 'сохранено (rev ' + wRev + ')') + '</span></div>';\n"
"      widgets.forEach((w, i) => {\n"
"        h += '<div class=\"wrow\"><label><input type=\"checkbox\"' + (w.on ? ' checked' : '') +\n"
"          ' onchange=\"wToggle(' + i + ',this.checked)\"> ' + widgetName(w) + '</label>';\n"
"        if (w.t === 'bar') {\n"
"          let sb = '<select onchange=\"wFlow(' + i + ',\\'mode\\',this.value)\">';\n"
"          for (const m in BARM) sb += '<option value=\"' + m + '\"' + (w.mode === m ? ' selected' : '') + '>' + BARM[m].n + '</option>';\n"
"          h += ' ' + sb + '</select> <button class=\"warn\" onclick=\"wDel(' + i + ')\">удалить</button>';\n"
"        }\n"
"        if (w.t === 'flow') {\n"
"          const sel = (which, map, names) => {\n"
"            let s = '<select onchange=\"wFlow(' + i + ',\\'' + which + '\\',this.value)\">';\n"
"            for (const u in map) s += '<option value=\"' + u + '\"' + (w[which] === u ? ' selected' : '') + '>' + names[u] + '</option>';\n"
"            return s + '</select>';\n"
"          };\n"
"          h += ' объём ' + sel('vol', VOLU, VOLN) + ' время ' + sel('time', TIMU, TIMN) +\n"
"            ' <button class=\"warn\" onclick=\"wDel(' + i + ')\">удалить</button>';\n"
"        }\n"
"        if (w.t === 'vol') {\n"
"          let s = '<select onchange=\"wFlow(' + i + ',\\'vol\\',this.value)\">';\n"
"          for (const u in VOLU) s += '<option value=\"' + u + '\"' + (w.vol === u ? ' selected' : '') + '>' + VOLN[u] + '</option>';\n"
"          h += ' объём ' + s + '</select>' +\n"
"            ' <button class=\"warn\" onclick=\"wDel(' + i + ')\">удалить</button>';\n"
"        }\n"
"        if (w.t === 'tot') {\n"
"          let sm = '<select onchange=\"wFlow(' + i + ',\\'m\\',this.value)\">';\n"
"          for (const u in TOTM) sm += '<option value=\"' + u + '\"' + (w.m === u ? ' selected' : '') + '>' + TOTM[u].n + '</option>';\n"
"          let sv = '<select onchange=\"wFlow(' + i + ',\\'vol\\',this.value)\">';\n"
"          for (const u in VOLU) sv += '<option value=\"' + u + '\"' + (w.vol === u ? ' selected' : '') + '>' + VOLN[u] + '</option>';\n"
"          h += ' ' + sm + '</select> ' + sv + '</select>' +\n"
"            ' <button class=\"warn\" onclick=\"wDel(' + i + ')\">удалить</button>';\n"
"        }\n"
"        if (w.t === 'bit') {\n"
"          let sg = '<select onchange=\"wBit(' + i + ',\\'src\\',this.value)\">';\n"
"          for (const g in FLAGS) sg += '<option value=\"' + g + '\"' + (w.src === g ? ' selected' : '') + '>' + (LBL[g] || g) + '</option>';\n"
"          let sb = '<select onchange=\"wBit(' + i + ',\\'b\\',this.value)\">';\n"
"          FLAGS[w.src].forEach((f, bi) => sb += '<option value=\"' + bi + '\"' + (w.b === bi ? ' selected' : '') + '>' + (FLBL[f] || f) + '</option>');\n"
"          h += ' ' + sg + '</select> ' + sb + '</select>' +\n"
"            ' цвет <input type=\"color\" value=\"' + w.col + '\" onchange=\"wBit(' + i + ',\\'col\\',this.value)\">' +\n"
"            ' <button class=\"warn\" onclick=\"wDel(' + i + ')\">удалить</button>';\n"
"        }\n"
"        h += '</div>';\n"
"      });\n"
"      const opts = VFLOATS.map(n => '<option value=\"' + n + '\">' + (LBL[n] || n) + '</option>').join('');\n"
"      h += '<div class=\"wrow\">＋ барграф <select id=\"nbMode\">';   \n"
"      for (const m in BARM) h += '<option value=\"' + m + '\"' + (m === 'qmax' ? ' selected' : '') + '>' + BARM[m].n + '</option>';\n"
"      h += '</select> <button onclick=\"wAddBar()\">Добавить</button></div>';\n"
"      h += '<div class=\"wrow\">＋ расход <select id=\"nwVol\">' +      \n"
"        '<option value=\"ml\">мл</option><option value=\"l\" selected>л</option><option value=\"m3\">м³</option></select>' +\n"
"        ' / <select id=\"nwTime\"><option value=\"s\">с</option><option value=\"m\" selected>мин</option>' +\n"
"        '<option value=\"h\">ч</option><option value=\"d\">сут</option></select>' +\n"
"        ' <button onclick=\"wAddFlow()\">Добавить</button></div>';\n"
"      h += '<div class=\"wrow\">＋ общий объём <select id=\"nvVol\">' + \n"
"        '<option value=\"ml\">мл</option><option value=\"l\" selected>л</option><option value=\"m3\">м³</option></select>' +\n"
"        ' <button onclick=\"wAddVol()\">Добавить</button></div>';\n"
"      h += '<div class=\"wrow\">＋ объём <select id=\"ntMode\">' +      \n"
"        '<option value=\"plus\" selected>Объём +</option><option value=\"minus\">Объём −</option>' +\n"
"        '<option value=\"diff\">Объём (+−)</option><option value=\"sum\">Объём (сумма)</option></select>' +\n"
"        ' <select id=\"ntVol\"><option value=\"ml\">мл</option><option value=\"l\" selected>л</option><option value=\"m3\">м³</option></select>' +\n"
"        ' <button onclick=\"wAddTot()\">Добавить</button></div>';\n"
"      h += '<div class=\"wrow\">＋ бит <select id=\"nbiSrc\">';         \n"
"      for (const g in FLAGS) h += '<option value=\"' + g + '\"' + (g === 'setpoint' ? ' selected' : '') + '>' + (LBL[g] || g) + '</option>';\n"
"      h += '</select> <select id=\"nbiBit\"></select>' +\n"
"        ' цвет <input id=\"nbiCol\" type=\"color\" value=\"' + BITCOL[0] + '\">' +\n"
"        ' <button onclick=\"wAddBit()\">Добавить</button></div>';\n"
"      p.innerHTML = h;\n"
"      { \n"
"        const g = $('nbiSrc').value, sel = $('nbiBit');\n"
"        sel.innerHTML = FLAGS[g].map((f, bi) => '<option value=\"' + bi + '\">' + (FLBL[f] || f) + '</option>').join('');\n"
"      }\n"
"    }\n"
"    function wToggle(i, on) { widgets[i].on = on; saveWidgets(); vBuild() }\n"
"    function wFlow(i, which, v) { widgets[i][which] = v; saveWidgets(); vBuild() }\n"
"    function wDel(i) { widgets.splice(i, 1); saveWidgets(); vBuild() }\n"
"    function wAddBar() {           \n"
"      widgets.push({ k: 'bar' + Date.now(), t: 'bar', mode: $('nbMode').value, on: true });\n"
"      saveWidgets(); vBuild();\n"
"    }\n"
"    function wAddFlow() {          \n"
"      widgets.push({ k: 'flow' + Date.now(), t: 'flow', vol: $('nwVol').value, time: $('nwTime').value, on: true });\n"
"      saveWidgets(); vBuild();\n"
"    }\n"
"    function wAddVol() {           \n"
"      widgets.push({ k: 'vol' + Date.now(), t: 'vol', vol: $('nvVol').value, on: true });\n"
"      saveWidgets(); vBuild();\n"
"    }\n"
"    function wAddTot() {           \n"
"      widgets.push({ k: 'tot' + Date.now(), t: 'tot', m: $('ntMode').value, vol: $('ntVol').value, on: true });\n"
"      saveWidgets(); vBuild();\n"
"    }\n"
"    function wAddBit() {           \n"
"      widgets.push({ k: 'bit' + Date.now(), t: 'bit', src: $('nbiSrc').value,\n"
"                     b: parseInt($('nbiBit').value) || 0, col: $('nbiCol').value, on: true });\n"
"      saveWidgets(); vBuild();\n"
"    }\n"
"    function wBit(i, which, v) {\n"
"      widgets[i][which] = which === 'b' ? parseInt(v) : v;\n"
"      saveWidgets(); vBuild();\n"
"    }\n"
"    document.addEventListener('change', e => {\n"
"      if (e.target.id !== 'nbiSrc') return;\n"
"      const sel = $('nbiBit');\n"
"      sel.innerHTML = FLAGS[e.target.value]\n"
"        .map((f, bi) => '<option value=\"' + bi + '\">' + (FLBL[f] || f) + '</option>').join('');\n"
"    });\n"
"    function vApply(d) {\n"
"      const barLo = vApply.lo || (vApply.lo = {}), barHi = vApply.hi || (vApply.hi = {});\n"
"      for (const n of VFLOATS) { const e = $('vf_' + n); if (e && d[n] !== undefined) e.textContent = d[n] }\n"
"      for (const n of VUINTS) { const e = $('vf_' + n); if (e && d[n] !== undefined) e.textContent = d[n] }\n"
"      for (const w of widgets || []) {\n"
"        if (w.t !== 'cval' || !w.on) continue;\n"
"        const c = CUSTOM[w.k], e = $('vfc_' + w.k);\n"
"        if (c && e && c.calc) {\n"
"          const v = c.calc(d, MY_CONST);\n"
"          if (isFinite(v)) e.textContent = String(v)\n"
"        }\n"
"      }\n"
"      for (const w of widgets || []) {\n"
"        if (w.t !== 'flow' || !w.on) continue;\n"
"        const e = $('vfl_' + w.k);\n"
"        if (e && d.rateMLPM !== undefined)\n"
"          e.textContent = Number((d.rateMLPM / VOLU[w.vol] * TIMU[w.time]).toPrecision(4))\n"
"      }\n"
"      for (const w of widgets || []) {\n"
"        if (w.t !== 'vol' || !w.on) continue;\n"
"        const e = $('vvv_' + w.k);\n"
"        if (e && d.gtotalml !== undefined)\n"
"          e.textContent = Number((d.gtotalml / VOLU[w.vol]).toPrecision(4))\n"
"      }\n"
"      for (const w of widgets || []) {\n"
"        if (w.t !== 'bit' || !w.on) continue;\n"
"        const e = $('bl_' + w.k);\n"
"        if (e && d[w.src] !== undefined) {\n"
"          const on = (d[w.src] >> w.b) & 1;\n"
"          e.style.background = on ? w.col : BITOFF;\n"
"          e.style.color = w.col;               \n"
"          e.classList.toggle('on', !!on);\n"
"        }\n"
"      }\n"
"      for (const w of widgets || []) {\n"
"        if (w.t !== 'tot' || !w.on) continue;\n"
"        const e = $('vtv_' + w.k), m = TOTM[w.m];\n"
"        if (e && m && d.totalml_plus !== undefined && d.totalml_minus !== undefined) {\n"
"          const v = m.c(d) / VOLU[w.vol];\n"
"          if (isFinite(v)) e.textContent = Number(v.toPrecision(4))\n"
"        }\n"
"      }\n"
"      for (const w of widgets || []) {\n"
"        if (w.t !== 'bar' || !w.on) continue;\n"
"        const m = BARM[w.mode], f = $('hf_' + w.k);\n"
"        const v = m ? d[m.src] : undefined;\n"
"        if (f && v !== undefined) {\n"
"          let hi = SP[w.mode];\n"
"          if (!(hi > 0)) {\n"
"            if (!(w.k in barLo) || v < barLo[w.k]) barLo[w.k] = v;\n"
"            if (!(w.k in barHi) || v > barHi[w.k]) barHi[w.k] = v;\n"
"            hi = barHi[w.k];\n"
"            if (hi - (barLo[w.k] || 0) < 1e-9) hi = (barLo[w.k] || 0) + 1;\n"
"          }\n"
"          const pct = Math.max(0, Math.min(100, v / hi * 100));\n"
"          f.style.width = pct.toFixed(1) + '%';\n"
"          const t = $('bp_' + w.k);\n"
"          if (t) t.textContent = pct.toFixed(0) + '%';\n"
"        }\n"
"      }\n"
"    }\n"
"    async function valuesTick() {\n"
"      try {\n"
"        const d = await (await fetch('/api/values')).json();\n"
"        if (d.link !== undefined) {\n"
"          $('link').textContent = d.link ? 'UART: связь есть' : 'UART: нет связи';\n"
"          $('link').className = 'tag ' + (d.link ? 'ok' : 'bad');\n"
"        }\n"
"        if (!d.ok) { return }\n"
"        if (!vBuilt) vBuild();\n"
"        vApply(d);\n"
"        if (d.rate !== undefined) { ratePush(d.rate); rateDraw() }\n"
"      } catch (e) { }\n"
"    }\n"
"    setInterval(valuesTick, 200); valuesTick();\n"
"    async function infoTick() {\n"
"      try {\n"
"        const r = await (await fetch('/api/info')).json();\n"
"        $('fw').textContent = r.fw + ' · параметров: ' + r.count;\n"
"        $('ip').textContent = r.ip;\n"
"        $('rss').textContent = r.ap ? r.rssi + ' dBm' : r.ssid + ': ' + r.rssi + ' dBm';\n"
"        $('upt').textContent = 'uptime ' + hms(r.uptime); $('heap').textContent = 'heap ' + (r.heap / 1024 | 0) + ' KiB';\n"
"      } catch (e) { }\n"
"    }\n"
"    async function paramsTick() {\n"
"      try {\n"
"        const d = await (await fetch('/api/params')).json();\n"
"        SP = {};\n"
"        for (const p of d.params) {\n"
"          if (p.t !== 0 || !p.w || !p.n) continue;\n"
"          for (const m in BARM)\n"
"            if (p.n === BARM[m].sp && (m === 'qmax' || p.tb === 'Уставки'))\n"
"              SP[m] = parseFloat(p.v);\n"
"        }\n"
"      } catch (e) { }\n"
"    }\n"
"    paramsTick(); setInterval(paramsTick, 30000);\n"
"    wSync();\n"
"    async function rescan() { await fetch('/api/rescan', { method: 'POST' }); infoTick(); paramsTick() }\n"
"    function rebootDev() { if (confirm('Перезагрузить прибор?')) fetch('/api/reboot', { method: 'POST' }) }\n"
"    infoTick(); setInterval(infoTick, 5000);</script>\n"
"</body>\n"
"\n"
"</html>\n";

